/* Offline lightweight Choices-compatible multi-select for this project */
(function(){
  function esc(s){return String(s||'').replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
  function Choices(select, opts){
    this.passedElement={element:select}; this.config=opts||{}; this.select=select; this.options=[].slice.call(select.options); this.dropdown={element:null}; this._build(); this._render();
  }
  Choices.prototype._build=function(){
    var s=this.select, self=this;
    var wrap=document.createElement('div'); wrap.className='choices is-hidden-select'; wrap.setAttribute('data-type','select-multiple');
    var inner=document.createElement('div'); inner.className='choices__inner';
    var selected=document.createElement('div'); selected.className='choices__list--multiple';
    var input=document.createElement('input'); input.type='text'; input.className='choices__input'; input.placeholder=this.config.placeholderValue||'';
    var dropdown=document.createElement('div'); dropdown.className='choices__list--dropdown'; dropdown.setAttribute('role','listbox');
    inner.appendChild(selected); inner.appendChild(input); wrap.appendChild(inner); wrap.appendChild(dropdown);
    s.parentNode.insertBefore(wrap,s); wrap.appendChild(s);
    this.container=wrap; this.inner=inner; this.selectedList=selected; this.input=input; this.dropdown.element=dropdown;
    inner.addEventListener('click',function(){ input.focus(); self.showDropdown(); });
    input.addEventListener('focus',function(){ wrap.classList.add('is-focused'); self.showDropdown(); });
    input.addEventListener('input',function(){ self._renderChoices(); self.showDropdown(); });
    document.addEventListener('click',function(e){ if(!wrap.contains(e.target)){ self.hideDropdown(); wrap.classList.remove('is-focused'); }});
    s.addEventListener('change',function(){ self._render(); });
  };
  Choices.prototype._selectedOptions=function(){return this.options.filter(function(o){return o.selected;});};
  Choices.prototype._render=function(){this._renderSelected(); this._renderChoices();};
  Choices.prototype._renderSelected=function(){
    var self=this, selected=this._selectedOptions(); this.selectedList.innerHTML='';
    if(!selected.length){ this.input.placeholder=this.config.placeholderValue||'Select'; }
    else { this.input.placeholder=''; }
    selected.forEach(function(o){
      var tag=document.createElement('span'); tag.className='choices__item choices__item--selectable'; tag.innerHTML=esc(o.text)+' ';
      if(self.config.removeItemButton){ var b=document.createElement('button'); b.type='button'; b.className='choices__button'; b.setAttribute('aria-label','Remove item'); b.innerHTML='×'; b.addEventListener('click',function(e){e.stopPropagation(); o.selected=false; self.select.dispatchEvent(new Event('change',{bubbles:true}));}); tag.appendChild(b); }
      self.selectedList.appendChild(tag);
    });
  };
  Choices.prototype._renderChoices=function(){
    var self=this, q=(this.input.value||'').toLowerCase(); this.dropdown.element.innerHTML=''; var count=0;
    this.options.forEach(function(o){
      if(!o.value) return; if(q && o.text.toLowerCase().indexOf(q)===-1) return; count++;
      var item=document.createElement('div'); item.className='choices__item choices__item--choice'+(o.selected?' is-selected':''); item.textContent=o.text;
      item.addEventListener('click',function(e){ e.preventDefault(); o.selected=!o.selected; self.input.value=''; self.select.dispatchEvent(new Event('change',{bubbles:true})); self._render(); self.showDropdown(); self.input.focus(); });
      self.dropdown.element.appendChild(item);
    });
    if(!count){ var empty=document.createElement('div'); empty.className='choices__empty'; empty.textContent='No courses found'; this.dropdown.element.appendChild(empty); }
  };
  Choices.prototype.showDropdown=function(){this.container.classList.add('is-open');};
  Choices.prototype.hideDropdown=function(){this.container.classList.remove('is-open');};
  Choices.prototype.getValue=function(){return this._selectedOptions().map(function(o){return {value:o.value,label:o.text};});};
  window.Choices=Choices;
})();
